<?php
declare(strict_types=1);
require __DIR__.'/../../config/app.php';
require __DIR__.'/../../config/forecast.php';
require __DIR__.'/../../includes/admin-layout.php';
$admin=at_admin();$pdo=at_db();
$from=(string)($_GET['from']??date('Y-m-01'));
$to=(string)($_GET['to']??date('Y-m-d'));
function at_date_valid(string $s): bool {$d=DateTimeImmutable::createFromFormat('!Y-m-d',$s);return $d!==false && $d->format('Y-m-d')===$s;}
if(!at_date_valid($from)||!at_date_valid($to)||$from>$to){http_response_code(400);exit('Invalid report date range.');}
$filters=[$from,$to];
// Completed orders are counted as sales. Payments represent cash collected independently.
$summaryQuery=$pdo->prepare("SELECT COUNT(*) orders_count,COALESCE(SUM(total_amount),0) total FROM orders WHERE order_status='Completed' AND DATE(order_date) BETWEEN ? AND ?");$summaryQuery->execute($filters);$summary=$summaryQuery->fetch();
$paymentStmt=$pdo->prepare('SELECT COALESCE(SUM(amount_paid),0) total,COUNT(*) count FROM payments WHERE DATE(payment_date) BETWEEN ? AND ?');$paymentStmt->execute($filters);$paymentSummary=$paymentStmt->fetch();
$orderQuery=$pdo->prepare('SELECT order_status,COUNT(*) qty FROM orders WHERE DATE(order_date) BETWEEN ? AND ? GROUP BY order_status ORDER BY qty DESC');$orderQuery->execute($filters);$orders=$orderQuery->fetchAll();
$dailyQuery=$pdo->prepare("SELECT DATE(order_date) day,COUNT(*) orders_count,COALESCE(SUM(total_amount),0) revenue FROM orders WHERE order_status='Completed' AND DATE(order_date) BETWEEN ? AND ? GROUP BY DATE(order_date) ORDER BY day DESC LIMIT 366");$dailyQuery->execute($filters);$daily=$dailyQuery->fetchAll();
$weeklyQuery=$pdo->prepare("SELECT YEARWEEK(order_date,3) week,MIN(DATE(order_date)) first_day, COUNT(*) orders_count,COALESCE(SUM(total_amount),0) revenue FROM orders WHERE order_status='Completed' AND DATE(order_date) BETWEEN ? AND ? GROUP BY YEARWEEK(order_date,3) ORDER BY week DESC LIMIT 104");$weeklyQuery->execute($filters);$weekly=$weeklyQuery->fetchAll();
$monthQuery=$pdo->query("SELECT DATE_FORMAT(o.order_date,'%Y-%m') month, COALESCE(SUM(o.total_amount),0) revenue FROM orders o WHERE o.order_status='Completed' GROUP BY DATE_FORMAT(o.order_date,'%Y-%m') ORDER BY month DESC LIMIT 12");$monthly=array_reverse($monthQuery->fetchAll());
$stock=$pdo->query('SELECT item_name,item_type,quantity,reorder_level,unit,status FROM inventory ORDER BY quantity ASC,item_name ASC LIMIT 300')->fetchAll();
$deliveries=$pdo->query('SELECT delivery_status,COUNT(*) qty FROM deliveries GROUP BY delivery_status')->fetchAll();
$forecast=at_sales_forecast($pdo);
if(isset($_GET['export'])){
 $type=(string)$_GET['export'];
 if(!in_array($type,['daily-sales','weekly-sales','orders','stock','deliveries'],true)){http_response_code(400);exit('Invalid export type.');}
 $name='aquatrack-'.$type.'-'.date('Ymd').'.csv';
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$name.'"');
 $out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");
 $clean=static function(mixed $v):string {$s=(string)$v;return preg_match('/^\s*[=+@-]/u',$s)?"'".$s:$s;};
 if($type==='daily-sales'){$cols=['Date','Completed orders','Revenue PHP'];$rows=array_map(fn($r)=>[$r['day'],$r['orders_count'],$r['revenue']],$daily);}
 elseif($type==='weekly-sales'){$cols=['ISO week','First completed order date in week','Completed orders','Revenue PHP'];$rows=array_map(fn($r)=>[$r['week'],$r['first_day'],$r['orders_count'],$r['revenue']],$weekly);}
 elseif($type==='orders'){$cols=['Status','Order count'];$rows=array_map(fn($r)=>[$r['order_status'],$r['qty']],$orders);}
 elseif($type==='stock'){$cols=['Item','Type','Stock','Reorder level','Unit','Status'];$rows=array_map(fn($r)=>array_values($r),$stock);}
 else{$cols=['Delivery status','Count'];$rows=array_map(fn($r)=>[$r['delivery_status'],$r['qty']],$deliveries);}
 fputcsv($out,$cols);foreach($rows as $r)fputcsv($out,array_map($clean,$r));fclose($out);exit;
}
at_open('Reports & Sales Forecasting','reports',(string)$admin['full_name'],'View operational reports and PHP-based next-month sales predictions.');
?><form class="op-filter op-no-print" method="get"><label class="op-field">From<input name="from" type="date" value="<?=at_h($from)?>" required></label><label class="op-field">To<input name="to" type="date" value="<?=at_h($to)?>" required></label><button class="op-button" type="submit">Apply Dates</button><button class="op-button secondary" type="button" onclick="window.print()">Print report</button></form>
<div class="op-summary"><article><span>Completed-order revenue</span><strong><?=at_peso($summary['total'])?></strong></article><article><span>Completed orders</span><strong><?=number_format((int)$summary['orders_count'])?></strong></article><article><span>Payments collected</span><strong><?=at_peso($paymentSummary['total'])?></strong></article><article><span>Payment transactions</span><strong><?=number_format((int)$paymentSummary['count'])?></strong></article></div>
<div class="op-grid op-grid-wide"><section class="op-card"><h2>Monthly completed-order sales</h2><p class="op-description">Up to 12 recorded months. Revenue is based on completed orders by order date.</p>
<?php $max=max(array_map(fn($r)=>(float)$r['revenue'],$monthly)?:[0]);?><div class="op-chart" role="img" aria-label="Monthly sales bar chart"><?php foreach($monthly as $m):?><div class="op-barcol" title="<?=at_h($m['month'].': '.at_peso($m['revenue']))?>"><div class="op-bar" style="height:<?= $max>0?max(2,round((float)$m['revenue']/$max*175)):2?>px"></div><span><?=at_h($m['month'])?></span></div><?php endforeach;?><?php if(!$monthly):?><p class="op-muted">No completed orders yet.</p><?php endif;?></div></section></div>
<div class="op-grid"><section class="op-card"><h2>Daily sales (filtered)</h2><p class="op-description">Completed orders grouped by order date.</p><div class="op-table-wrap"><table class="op-table"><thead><tr><th>Date</th><th>Orders</th><th>Revenue</th></tr></thead><tbody><?php foreach($daily as $d):?><tr><td><?=at_h($d['day'])?></td><td><?=$d['orders_count']?></td><td><?=at_peso($d['revenue'])?></td></tr><?php endforeach;?><?php if(!$daily):?><tr><td colspan="3">No sales in selected range.</td></tr><?php endif;?></tbody></table></div><p class="op-hint">Up to 366 daily rows displayed/exported.</p><a class="op-button secondary op-no-print" href="?<?=at_h(http_build_query(['from'=>$from,'to'=>$to,'export'=>'daily-sales']))?>">Export CSV</a></section>
<section class="op-card"><h2>Order status breakdown</h2><p class="op-description">All statuses, filtered by order date.</p><div class="op-table-wrap"><table class="op-table"><thead><tr><th>Status</th><th>Count</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=at_h($o['order_status'])?></td><td><?=$o['qty']?></td></tr><?php endforeach;?><?php if(!$orders):?><tr><td colspan="2">No orders.</td></tr><?php endif;?></tbody></table></div><a class="op-button secondary op-no-print" href="?<?=at_h(http_build_query(['from'=>$from,'to'=>$to,'export'=>'orders']))?>">Export CSV</a></section></div>
<section class="op-card"><h2>Weekly sales</h2><p class="op-description">ISO weeks and completed-order sales within the selected date range.</p><div class="op-table-wrap"><table class="op-table"><thead><tr><th>ISO week</th><th>Week start (first included sale)</th><th>Completed orders</th><th>Revenue</th></tr></thead><tbody><?php foreach($weekly as $w):?><tr><td><?=at_h($w['week'])?></td><td><?=at_h($w['first_day'])?></td><td><?=$w['orders_count']?></td><td><?=at_peso($w['revenue'])?></td></tr><?php endforeach;?><?php if(!$weekly):?><tr><td colspan="4">No weekly sales in selected range.</td></tr><?php endif;?></tbody></table></div><a class="op-button secondary op-no-print" href="?<?=at_h(http_build_query(['from'=>$from,'to'=>$to,'export'=>'weekly-sales']))?>">Export Weekly CSV</a></section>
<div class="op-grid"><section class="op-card"><h2>Stock levels</h2><p class="op-description">Current inventory levels (not restricted by report dates).</p><div class="op-table-wrap"><table class="op-table"><thead><tr><th>Item</th><th>Stock</th><th>Status</th></tr></thead><tbody><?php foreach($stock as $s):?><tr><td><?=at_h($s['item_name'])?></td><td><?=$s['quantity']?> <?=at_h($s['unit']??'')?></td><td><?=at_h($s['status'])?></td></tr><?php endforeach;?><?php if(!$stock):?><tr><td colspan="3">No supplies recorded.</td></tr><?php endif;?></tbody></table></div><a class="op-button secondary op-no-print" href="?<?=at_h(http_build_query(['from'=>$from,'to'=>$to,'export'=>'stock']))?>">Export CSV</a></section>
<section class="op-card"><h2>Delivery performance</h2><p class="op-description">Current lifetime delivery status distribution.</p><div class="op-table-wrap"><table class="op-table"><thead><tr><th>Status</th><th>Count</th></tr></thead><tbody><?php foreach($deliveries as $d):?><tr><td><?=at_h($d['delivery_status'])?></td><td><?=$d['qty']?></td></tr><?php endforeach;?><?php if(!$deliveries):?><tr><td colspan="2">No deliveries recorded.</td></tr><?php endif;?></tbody></table></div><a class="op-button secondary op-no-print" href="?<?=at_h(http_build_query(['from'=>$from,'to'=>$to,'export'=>'deliveries']))?>">Export CSV</a></section></div>
<section class="op-card" id="forecast"><h2>Machine Learning — Next Month Sales Forecast</h2><p class="op-description">Native PHP linear regression using complete months of historical sales records. Forecasting uses completed orders represented in the sales table, by sale date. No Python or external API.</p>
<?php if(!$forecast['sufficient']):?><div class="op-notice bad"><strong>Insufficient Data.</strong> At least six complete months of recorded sales history are needed. For seasonal forecasting, 12–24 months is preferable. Current history: <?=count($forecast['history'])?> complete month(s).</div>
<?php else:?><div class="op-stat-hero"><small>Predicted revenue for <?=at_h($forecast['next_month'])?></small><strong><?=at_peso($forecast['forecast'])?></strong><small>Exploratory forecast, not guaranteed revenue.</small></div>
<div class="op-forecast-detail"><div><small>Training months</small><strong><?=$forecast['months']?></strong></div><div><small>Walk-forward MAE</small><strong><?=at_peso($forecast['mae'])?></strong></div><div><small>Baseline MAE / MAPE</small><strong><?=at_peso($forecast['baseline_mae'])?></strong><small>Regression MAPE: <?= $forecast['mape']===null?'N/A (zero actuals)':at_h($forecast['mape']).'%' ?></small></div></div>
<p class="op-hint">MAE is the average absolute peso error over up to three historical one-month-ahead predictions. A higher ML MAE than the baseline means regression has not beaten the simple baseline. Months with no records after the first recorded sale are treated as zero and may reflect missing data.</p>
<?php endif;?><div class="op-table-wrap"><table class="op-table"><thead><tr><th>Historical month</th><th>Completed sale revenue</th></tr></thead><tbody><?php foreach(array_reverse($forecast['history']) as $r):?><tr><td><?=at_h($r['month'])?></td><td><?=at_peso($r['revenue'])?></td></tr><?php endforeach;?><?php if(!$forecast['history']):?><tr><td colspan="2">No eligible sales history yet.</td></tr><?php endif;?></tbody></table></div></section>
<?php at_close();
